<#.SYNOPSISFetch recent Lambda function error logs from CloudWatch..DESCRIPTIONPulls logs for the last 24 hours for all functions and highlights errors.#>Import-Module AWSPowerShell.NetCoreWrite-Host "=== Lambda Error Log Scan (last 24 hours) ==="$functions = Get-LMFunctionListforeach ($fn in $functions.Functions) {$fnName = $fn.FunctionName    # Fetch log streams    $streams = Get-CWLLogStream -LogGroupName "/aws/lambda/$fnName" -OrderBy "LastEventTime" -Descending    foreach ($stream in $streams) {        $events = Get-CWLLogEvent -LogGroupName "/aws/lambda/$fnName" -LogStreamName $stream.LogStreamName -StartTime ((Get-Date).AddDays(-1))        foreach ($e in $events) {            if ($e.Message -match "ERROR" -or $e.Message -match "Exception") {                Write-Host "[$fnName][$($stream.LogStreamName)] $($e.Timestamp): $($e.Message)" -ForegroundColor Red            }        }    }}